<?php namespace Workspace; ?>
<section class="panel inset"><form method="get" class="inline"><input type="hidden" name="p" value="signing"><label>Проект<select name="project" required><option value="">Выберите проект</option><?php selectOptions($projects,$selected) ?></select></label><button>Открыть</button></form></section>
<?php if(!$selected)return; ?>
<p><a href="<?= h(url('preparation',['project'=>$selected])) ?>">Согласование документов</a></p>
<?php if(!$configured): ?><p>Провайдер для этой организации не настроен. Архив доступен независимо от подключения.</p><?php endif ?>
<?php if($configured&&$user['role']==='owner'): ?><section class="panel inset"><h2>Новый пакет Dropbox Sign <?= $test?'(TEST — не юридически значимый)':'(LIVE)' ?></h2><p>Пакет передаёт согласованный PDF и адреса двух подписантов внешнему провайдеру. Проверьте их полномочия и адреса до отправки. Сервис добавляет страницу подписей. Worker отправляет пакет только один раз.</p>
<?php foreach($approved as $a): ?><details><summary><?= h($a['title'].' · v'.$a['revision']) ?></summary><form method="post"><?php formFields('sign.create') ?><input type="hidden" name="mode" value="<?= h($test) ?>"><input type="hidden" name="project_id" value="<?= h($selected) ?>"><input type="hidden" name="preparation_id" value="<?= h($a['id']) ?>"><input type="hidden" name="revision_id" value="<?= h($a['revision_id']) ?>"><?php foreach([1,2] as $i): ?><label>Имя подписанта <?= $i ?><input name="name<?= $i ?>" required maxlength="100"></label><label>Email подписанта <?= $i ?><input name="email<?= $i ?>" type="email" required maxlength="254"></label><?php endforeach ?><label><input type="checkbox" name="confirm" value="yes" required> Подтверждаю отправку точной согласованной редакции и адресов провайдеру</label><button>Поставить на отправку</button></form></details><?php endforeach ?></section><?php endif ?>
<section class="panel inset"><h2>Пакеты</h2><?php foreach(array_slice($packages,0,50) as $a): ?><p><a href="<?= h(url('signing',['project'=>$selected,'id'=>$a['id']])) ?>">Пакет #<?= h($a['id']) ?></a> · <?= h(SIGN_STATES[$a['state']]) ?> · <?= $a['test_mode']?'TEST':'LIVE' ?> · редакция #<?= h($a['revision_id']) ?></p><?php endforeach ?><?php if(count($packages)>50): ?><a href="<?= h(url('signing',['project'=>$selected,'before'=>$packages[49]['id']])) ?>">Следующая страница</a><?php endif ?></section>
<?php if(!$package)return; $j=$package;$id=$j['id'];$link=fn($kind)=>url('sign.download',['project'=>$selected,'id'=>$id,'kind'=>$kind]); ?>
<section class="panel inset"><h2>Пакет #<?= h($id) ?> · <?= h(SIGN_STATES[$j['state']]) ?> · <?= $j['test_mode']?'TEST':'LIVE' ?></h2><p>Dropbox Sign ID: <?= h($j['remote_id']??'нет') ?> · nonce: <code><?= h($j['nonce']) ?></code></p><p>Снимок: <code><?= h($j['evidence_hash']) ?></code></p><p><?= h($j['last_error']) ?></p><p>Подписанты: <?php foreach(signDecode($j['signers_json']) as $s): ?><?= h($s['name'].' ('.$s['email_address'].')') ?>; <?php endforeach ?></p><p><a href="<?= h($link('original')) ?>">Исходный PDF</a><?php if($j['state']==='archived'): ?> · <a href="<?= h($link('signed')) ?>">Подписанный оригинал с audit trail</a> · <a href="<?= h($link('evidence')) ?>">Комплект доказательств JSON</a><?php endif ?><?php if($j['status_receipt']||$j['send_receipt']): ?> · <a href="<?= h($link('receipt')) ?>">Квитанция API</a><?php endif ?> · <a href="<?= h($link('receipts')) ?>">Реестр квитанций <?= $j['test_mode']?'TEST (не юридическая подпись)':'LIVE' ?> JSON</a></p>
<?php if($user['role']==='owner'&&$j['state']==='queued'): ?><form method="post"><?php formFields('sign.cancel') ?><input type="hidden" name="project_id" value="<?= h($selected) ?>"><input type="hidden" name="id" value="<?= h($id) ?>"><button>Отменить до отправки</button></form><?php endif ?>
<?php if($configured&&$user['role']==='owner'&&in_array($j['state'],['pending','partial','provider_error','uncertain'],true)): ?><form method="post"><?php formFields($j['state']==='uncertain'?'sign.adopt':'sign.sync') ?><input type="hidden" name="project_id" value="<?= h($selected) ?>"><input type="hidden" name="id" value="<?= h($id) ?>"><?php if($j['state']==='uncertain'): ?><label>Существующий ID из Dropbox Sign Dashboard<input name="remote_id" required pattern="[a-f0-9]{40}"></label><?php endif ?><button>Сверить с провайдером</button></form><?php endif ?>
<h3>Подписанные callback-квитанции</h3><?php foreach($callbacks as $e): ?><p><?= h(gmdate('Y-m-d H:i:s',(int)$e['event_time'])) ?> UTC · <?= h($e['event_type']) ?> · <a href="<?= h($link((string)$e['id'])) ?>">Квитанция #<?= h($e['id']) ?></a></p><?php endforeach ?></section>
